import { isAbsolute } from "node:path";
// The subset of the Codex app-server protocol Mobius drives. The surface is generated by
// `codex app-server generate-ts` and is not stable across Codex versions, so Mobius declares only the
// methods and fields it actually reads and validates every inbound payload at the boundary.
import { z } from "zod";

const boundedText = (maximum: number): z.ZodString => z.string().max(maximum);
const jsonValue: z.ZodType<unknown> = z.lazy(() => z.unknown());

const requestIdSchema = z
    .union([z.number(), z.string()])
    .refine((value) => typeof value === "number" || value.length <= 256);

const errorResponseSchema = z.object({
    error: z.object({ code: z.number(), message: boundedText(4_096) }),
    id: requestIdSchema,
});
const resultResponseSchema = z.object({ id: requestIdSchema, result: z.unknown() });
const serverRequestSchema = z.object({
    id: requestIdSchema,
    method: z.string(),
    params: z.unknown().optional(),
});
const serverNotificationSchema = z.object({
    method: z.string(),
    params: z.unknown().optional(),
});

// A message is classified before it is decoded further: responses carry `id` without `method`,
// server-initiated requests carry both, and notifications carry `method` alone.
export type AppServerMessage =
    | { readonly kind: "error-response"; readonly id: number | string; readonly message: string; readonly code: number }
    | { readonly kind: "result-response"; readonly id: number | string; readonly result: unknown }
    | {
          readonly kind: "server-request";
          readonly id: number | string;
          readonly method: string;
          readonly params: unknown;
      }
    | { readonly kind: "notification"; readonly method: string; readonly params: unknown };

export function decodeAppServerMessage(value: unknown): AppServerMessage {
    const record = z.record(z.string(), z.unknown()).parse(value);
    const error = errorResponseSchema.safeParse(record);
    if (error.success) {
        return {
            code: error.data.error.code,
            id: error.data.id,
            kind: "error-response",
            message: error.data.error.message,
        };
    }
    const result = resultResponseSchema.safeParse(record);
    if (result.success) {
        return { id: result.data.id, kind: "result-response", result: result.data.result };
    }
    const request = serverRequestSchema.safeParse(record);
    if (request.success) {
        return {
            id: request.data.id,
            kind: "server-request",
            method: request.data.method,
            params: request.data.params ?? {},
        };
    }
    const notification = serverNotificationSchema.parse(record);
    return { kind: "notification", method: notification.method, params: notification.params ?? {} };
}

const turnStatusSchema = z.enum(["inProgress", "completed", "interrupted", "failed"]);
const messagePhaseSchema = z.enum(["commentary", "final_answer"]);
const commandExecutionStatusSchema = z.enum(["inProgress", "completed", "failed", "declined"]);
const patchApplyStatusSchema = z.enum(["inProgress", "completed", "failed", "declined"]);
const mcpToolCallStatusSchema = z.enum(["inProgress", "completed", "failed"]);
const dynamicToolCallStatusSchema = z.enum(["inProgress", "completed", "failed"]);
const collabAgentToolCallStatusSchema = z.enum(["inProgress", "completed", "failed", "interrupted"]);

export type ThreadItem = z.infer<typeof threadItemSchema>;

const fileUpdateChangeSchema = z.object({
    diff: boundedText(1_000_000),
    kind: z.unknown(),
    path: boundedText(4_096),
});

const imageGenerationItemSchema = z.object({
    id: boundedText(256),
    type: z.literal("imageGeneration"),
    status: boundedText(80),
    revisedPrompt: boundedText(32_768).nullish(),
    // The app-server frame is bounded; media validation belongs to the content externalizer.
    result: z.string(),
    failure: z
        .object({
            type: z.literal("usageLimitExceeded"),
            limitId: boundedText(256),
            resetsAt: z.number().nullish(),
        })
        .nullish(),
});

// `ThreadItem` is an open union: a newer Codex can add a variant at any time. Decode the shape Mobius
// reads and skip anything else rather than failing the whole stream.
export const threadItemSchema = z.discriminatedUnion("type", [
    imageGenerationItemSchema,
    z.object({ type: z.literal("imageView"), id: boundedText(256), path: boundedText(32_768).refine(isAbsolute) }),
    z.object({
        id: boundedText(256),
        text: boundedText(1_000_000),
        type: z.literal("agentMessage"),
        phase: messagePhaseSchema.nullish(),
    }),
    z.object({ content: z.array(z.unknown()).max(10_000), id: boundedText(256), type: z.literal("userMessage") }),
    z.object({
        aggregatedOutput: boundedText(4_000_000).nullish(),
        command: boundedText(32_768),
        cwd: boundedText(4_096),
        durationMs: z.number().nullish(),
        exitCode: z.number().nullish(),
        id: boundedText(256),
        processId: z.string().nullish(),
        status: commandExecutionStatusSchema,
        type: z.literal("commandExecution"),
    }),
    z.object({
        changes: z.array(fileUpdateChangeSchema).max(10_000),
        id: boundedText(256),
        status: patchApplyStatusSchema,
        type: z.literal("fileChange"),
    }),
    z.object({
        arguments: jsonValue.optional(),
        error: z.unknown().nullish(),
        id: boundedText(256),
        result: z.unknown().nullish(),
        server: boundedText(256),
        status: mcpToolCallStatusSchema,
        tool: boundedText(256),
        type: z.literal("mcpToolCall"),
    }),
    z.object({
        arguments: jsonValue.optional(),
        contentItems: z.array(z.unknown()).max(10_000).nullish(),
        id: boundedText(256),
        namespace: z.string().nullish(),
        status: dynamicToolCallStatusSchema,
        success: z.boolean().nullish(),
        tool: boundedText(256),
        type: z.literal("dynamicToolCall"),
    }),
    z.object({
        content: z.array(boundedText(1_000_000)).max(1_000),
        id: boundedText(256),
        summary: z.array(boundedText(1_000_000)).max(1_000),
        type: z.literal("reasoning"),
    }),
    z.object({ id: boundedText(256), text: boundedText(1_000_000), type: z.literal("plan") }),
    z.object({
        agentPath: boundedText(4_096),
        agentThreadId: boundedText(256),
        id: boundedText(256),
        kind: z.enum(["started", "interacted", "interrupted", "completed"]),
        type: z.literal("subAgentActivity"),
    }),
    z.object({
        agentsStates: z
            .record(
                boundedText(256),
                z.object({
                    message: boundedText(32_768).nullish(),
                    status: z.enum([
                        "pendingInit",
                        "running",
                        "interrupted",
                        "completed",
                        "errored",
                        "shutdown",
                        "notFound",
                    ]),
                }),
            )
            .refine((states) => Object.keys(states).length <= 1_000),
        id: boundedText(256),
        model: boundedText(256).nullish(),
        prompt: boundedText(1_000_000).nullish(),
        reasoningEffort: boundedText(80).nullish(),
        receiverThreadIds: z.array(boundedText(256)).max(1_000),
        senderThreadId: boundedText(256),
        status: collabAgentToolCallStatusSchema,
        tool: z.enum(["spawnAgent", "wait"]),
        type: z.literal("collabAgentToolCall"),
    }),
]);

export const turnSchema = z.object({
    durationMs: z.number().nullish(),
    error: z.object({ message: boundedText(4_096) }).nullish(),
    id: boundedText(256),
    status: turnStatusSchema,
});

export const turnSteerResponseSchema = z.object({ turnId: boundedText(256) });

export const turnNotificationSchema = z.object({
    thread: z.object({ id: boundedText(256) }).nullish(),
    threadId: boundedText(256),
    turn: turnSchema,
});

export const errorNotificationSchema = z.object({
    error: z.object({ message: boundedText(4_096) }),
    threadId: boundedText(256),
    turnId: boundedText(256),
    willRetry: z.boolean(),
});

export const commandApprovalParamsSchema = z.object({
    command: z.string().nullish(),
    commandActions: z.array(z.unknown()).max(1_000).nullish(),
    cwd: z.string().nullish(),
    itemId: boundedText(256),
    reason: z.string().nullish(),
    threadId: boundedText(256),
    turnId: boundedText(256),
});

export const fileChangeApprovalParamsSchema = z.object({
    grantRoot: z.string().nullish(),
    itemId: boundedText(256),
    reason: z.string().nullish(),
    threadId: boundedText(256),
    turnId: boundedText(256),
});

const userInputOptionSchema = z.object({
    description: boundedText(4_096),
    label: boundedText(1_024),
});
const userInputQuestionSchema = z.object({
    header: boundedText(1_024),
    id: boundedText(256),
    options: z.array(userInputOptionSchema).max(1_000).nullish(),
    question: boundedText(4_096),
});
export const requestUserInputParamsSchema = z.object({
    itemId: boundedText(256).nullish(),
    questions: z.array(userInputQuestionSchema).max(1_000),
    threadId: boundedText(256),
    turnId: boundedText(256),
});

export const reasoningTextDeltaParamsSchema = z.object({
    delta: boundedText(100_000),
    itemId: boundedText(256),
    threadId: boundedText(256),
    turnId: boundedText(256),
});

export const mcpElicitationParamsSchema = z.object({
    message: boundedText(4_096),
    mode: z.enum(["form", "url"]).or(z.string()),
    requestedSchema: z.unknown().optional(),
    serverName: boundedText(256),
    threadId: boundedText(256).nullish(),
    turnId: boundedText(256).nullish(),
    url: z.string().optional(),
});

export const threadStartResponseSchema = z.object({
    approvalPolicy: z.unknown().optional(),
    approvalsReviewer: z.unknown().optional(),
    model: boundedText(256).nullish(),
    reasoningEffort: boundedText(256).nullish(),
    sandbox: z.unknown().optional(),
    serviceTier: boundedText(256).nullish(),
    thread: z.object({ id: boundedText(256) }),
});

const threadTurnSchema = z.object({
    id: boundedText(256).optional(),
    status: turnStatusSchema.optional(),
    items: z.array(z.unknown()).max(100_000),
});
const threadTurnsSchema = z.array(threadTurnSchema).max(100_000);
const collaborationModeSchema = z.object({
    mode: z.enum(["default", "plan"]),
});
const threadLifecycleResponseSchema = z.object({
    collaborationMode: collaborationModeSchema.nullish(),
    model: boundedText(256).nullish(),
    reasoningEffort: boundedText(256).nullish(),
    serviceTier: boundedText(256).nullish(),
    thread: z.object({ id: boundedText(256), turns: threadTurnsSchema }),
});

export const CODEX_HISTORY_TURN_PAGE_LIMIT = 20;
export const threadTurnsPageSchema = z.object({
    data: z.array(threadTurnSchema).max(CODEX_HISTORY_TURN_PAGE_LIMIT),
    nextCursor: boundedText(1_024).nullish(),
});

export const threadResumeResponseSchema = threadLifecycleResponseSchema;
export const threadForkResponseSchema = threadLifecycleResponseSchema;

// A thread summary as `thread/list` reports it. `updatedAt` is Unix seconds and becomes the ACP
// session's ISO 8601 timestamp; `name` is the user-facing title with `preview` — usually the first
// user message — as the fallback label. Codex does not bound either title source, while ACP limits
// a native session title to 500 characters, so normalize the validated strings at this boundary.
const threadTitleSchema = z.string().transform((value) => value.slice(0, 500));
const threadSummarySchema = z.object({
    cwd: boundedText(2_048),
    id: boundedText(256),
    name: threadTitleSchema.nullish(),
    preview: threadTitleSchema.nullish(),
    updatedAt: z.number().int().nonnegative(),
});

export const threadListResponseSchema = z.object({
    data: z.array(threadSummarySchema).max(500),
    nextCursor: boundedText(1_024).nullish(),
});

const reasoningEffortOptionSchema = z.object({
    description: boundedText(4_096).nullish(),
    reasoningEffort: boundedText(256),
});

// A model Mobius can offer as a setting. Only `id` is load-bearing: the display name falls back to
// it and a missing default effort leaves the effort option without a recommendation.
const modelSchema = z.object({
    additionalSpeedTiers: z.array(boundedText(256)).max(100).nullish(),
    defaultReasoningEffort: boundedText(256).nullish(),
    description: boundedText(4_096).nullish(),
    displayName: boundedText(256).nullish(),
    id: boundedText(256),
    isDefault: z.boolean().nullish(),
    supportedReasoningEfforts: z.array(reasoningEffortOptionSchema).max(100).nullish(),
});

export const modelListResponseSchema = z.object({
    data: z.array(modelSchema).max(1_000),
    nextCursor: boundedText(1_024).nullish(),
});

// The collaboration mode half of a `thread/settings/updated` notification. Only the mode name is
// load-bearing for Mobius; the mode's settings repeat the model and effort already tracked from the
// thread lifecycle, and the developer instructions belong to Codex, not the settings panel.
export const threadSettingsUpdatedSchema = z.object({
    threadId: boundedText(256),
    threadSettings: z.object({
        collaborationMode: collaborationModeSchema.nullish(),
    }),
});

export type McpElicitationParams = z.infer<typeof mcpElicitationParamsSchema>;
export type UserInputQuestion = z.infer<typeof userInputQuestionSchema>;
export type CodexModel = z.infer<typeof modelSchema>;
